<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { api } from '../../services/api.js';
import { workspace, loadStores } from '../../services/workspace.js';
import { canFeature } from '../../services/auth.js';
import { notify } from '../../services/notifications.js';
import Icon from '../../components/Icon.vue';

const loading=ref(true),saving=ref(false),verifying=ref(false),error=ref('');
const domain=reactive({mode:'path',subdomain:'',customDomain:'',status:'unconfigured',publicUrl:'',pathUrl:'',baseDomain:'mitiendaya.com.ar',cnameTarget:'',verification:null,verifiedAt:null,dnsVerifiedAt:null,provisionedAt:null,provisioningError:'',provisioningEnabled:false});
const managedUrl=computed(()=>domain.subdomain?`https://${domain.subdomain}.${domain.baseDomain}`:'');
const statusLabel=computed(()=>{
  if(domain.mode!=='custom') return 'Activo';
  if(domain.status==='verified') return 'Dominio activo';
  if(domain.provisioningError) return 'Error al activar';
  if(domain.dnsVerifiedAt) return 'Verificado · activación pendiente';
  return 'Pendiente de verificación';
});
const statusClass=computed(()=>domain.mode!=='custom'||domain.status==='verified'?'badge-success':domain.provisioningError?'badge-error':'badge-warning');

async function load(){loading.value=true;error.value='';try{Object.assign(domain,await api.get(`/stores/${workspace.activeStoreId}/domain`))}catch(e){error.value=e.message}finally{loading.value=false}}
onMounted(load);
async function save(){saving.value=true;error.value='';try{const result=await api.put(`/stores/${workspace.activeStoreId}/domain`,{mode:domain.mode,subdomain:domain.subdomain,customDomain:domain.customDomain});Object.assign(domain,result);await loadStores();notify.success('Dominio de la tienda actualizado.')}catch(e){error.value=e.message;notify.error(e.message)}finally{saving.value=false}}
async function verify(){verifying.value=true;error.value='';try{Object.assign(domain,await api.post(`/stores/${workspace.activeStoreId}/domain/verify`,{}));await loadStores();notify.success('Dominio verificado y activado correctamente.')}catch(e){error.value=e.message;domain.provisioningError=e.message;notify.error(e.message);try{Object.assign(domain,await api.get(`/stores/${workspace.activeStoreId}/domain`))}catch{}}finally{verifying.value=false}}
async function copy(value){try{await navigator.clipboard.writeText(value);notify.success('Copiado.')}catch{notify.info('Seleccioná y copiá el valor manualmente.')}}
</script>

<template><div><header class="p-page-header"><div><p class="p-eyebrow">DIRECCIÓN DE TU TIENDA</p><h1>Dominio</h1><p>Elegí cómo querés que tus clientes encuentren esta tienda.</p></div><a v-if="domain.publicUrl" :href="domain.publicUrl" class="btn btn-secondary" target="_blank" rel="noopener"><Icon name="external" :size="16"/>Abrir tienda</a></header><div v-if="error" class="p-error">{{error}}</div><div v-if="loading" class="p-loading-page"><span class="p-spinner"/></div><form v-else class="p-form" @submit.prevent="save"><section class="p-section-card"><div class="p-section-title"><div><h2>Dirección pública</h2><p>La dirección clásica siempre queda disponible como respaldo.</p></div><Icon name="globe"/></div><div class="domain-modes"><label class="domain-mode" :class="{selected:domain.mode==='path'}"><input v-model="domain.mode" type="radio" value="path"/><span><strong>Enlace de MiTiendaYa</strong><small>Usa la dirección /t/ de la tienda, sin configuraciones adicionales.</small></span></label><label v-if="canFeature('domain.subdomain')||domain.mode==='subdomain'" class="domain-mode" :class="{selected:domain.mode==='subdomain'}"><input v-model="domain.mode" type="radio" value="subdomain" :disabled="!canFeature('domain.subdomain')"/><span><strong>Subdominio propio de la plataforma</strong><small>Ejemplo: mi-marca.{{domain.baseDomain}}</small></span></label><label v-if="canFeature('domain.custom')||domain.mode==='custom'" class="domain-mode" :class="{selected:domain.mode==='custom'}"><input v-model="domain.mode" type="radio" value="custom" :disabled="!canFeature('domain.custom')"/><span><strong>Dominio propio</strong><small>Ejemplo: tienda.mi-marca.com</small></span></label></div><div v-if="domain.pathUrl" class="domain-permanent-path"><span>Enlace permanente de MiTiendaYa</span><a :href="domain.pathUrl" target="_blank" rel="noopener">{{domain.pathUrl}}</a><small>Este enlace siempre queda disponible aunque uses un dominio o subdominio.</small></div><div v-if="domain.mode==='subdomain'" class="p-form-grid domain-fields"><div class="p-field full"><label for="store-subdomain">Subdominio</label><div class="domain-input"><input id="store-subdomain" v-model.trim="domain.subdomain" required minlength="3" maxlength="63" pattern="[a-z0-9](?:[a-z0-9-]{1,61}[a-z0-9])?" placeholder="mi-marca"/><span>.{{domain.baseDomain}}</span></div><small v-if="managedUrl">{{managedUrl}}</small></div></div><div v-if="domain.mode==='custom'" class="p-form-grid domain-fields"><div class="p-field full"><label for="custom-domain">Dominio propio</label><input id="custom-domain" v-model.trim="domain.customDomain" required maxlength="253" placeholder="tienda.mi-marca.com"/><small>Ingresá sólo el dominio, sin rutas. Podés pegar una URL completa y se normalizará al guardar.</small></div></div></section><section v-if="domain.mode==='custom' && domain.customDomain && domain.verification" class="p-section-card"><div class="p-section-title"><div><h2>Verificación del dominio</h2><p>Agregá estos datos en el proveedor donde administrás tu dominio y luego verificá la configuración.</p></div><span class="badge" :class="statusClass">{{statusLabel}}</span></div><div class="domain-records"><div><span>TXT</span><strong>{{domain.verification.name}}</strong><code>{{domain.verification.value}}</code><button type="button" class="p-icon-btn" @click="copy(domain.verification.value)" aria-label="Copiar valor TXT"><Icon name="copy" :size="16"/></button></div><div><span>CNAME / ALIAS</span><strong>{{domain.customDomain}}</strong><code>{{domain.cnameTarget}}</code><button type="button" class="p-icon-btn" @click="copy(domain.cnameTarget)" aria-label="Copiar destino CNAME"><Icon name="copy" :size="16"/></button></div></div><div v-if="domain.provisioningError" class="p-error domain-provisioning-error">{{domain.provisioningError}}</div><div class="p-inline domain-verify"><button v-if="canFeature('domain.custom')" type="button" class="btn btn-secondary" :disabled="verifying||domain.status==='verified'" @click="verify">{{domain.status==='verified'?'Dominio activo':verifying?'Validando y activando…':'Verificar y activar dominio'}}</button><small v-if="domain.status!=='verified' && !domain.provisioningEnabled">La activación automática de dominios no está disponible en este momento. Contactá a la administración.</small><small v-else-if="domain.status!=='verified'">Agregá los registros indicados y esperá a que se actualicen. Luego presioná “Verificar y activar dominio”.</small><small v-else>Dirección segura activa: <a :href="domain.publicUrl" target="_blank" rel="noopener">{{domain.publicUrl}}</a></small></div></section><footer class="p-form-footer"><small><span class="badge" :class="statusClass">{{statusLabel}}</span><template v-if="domain.publicUrl"> · {{domain.publicUrl}}</template></small><div class="p-form-actions"><button class="btn btn-primary" :disabled="saving">{{saving?'Guardando…':'Guardar dominio'}}</button></div></footer></form></div></template>

<style scoped>
.domain-modes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.domain-mode{border:1px solid var(--line);border-radius:12px;padding:18px;display:flex;align-items:flex-start;gap:12px;cursor:pointer;background:var(--surface)}.domain-mode.selected{border-color:var(--primary);box-shadow:0 0 0 2px color-mix(in srgb,var(--primary) 14%,transparent)}.domain-mode input{margin-top:3px}.domain-mode span{display:flex;flex-direction:column;gap:5px}.domain-mode small{color:var(--muted);font-weight:400}.domain-permanent-path{margin-top:16px;padding:13px 15px;border:1px solid var(--line);border-radius:10px;background:var(--surface-alt);display:grid;gap:4px}.domain-permanent-path span{font-size:.75rem;font-weight:750;color:var(--muted);text-transform:uppercase;letter-spacing:.04em}.domain-permanent-path a{font-weight:700;overflow-wrap:anywhere}.domain-permanent-path small{color:var(--muted)}.domain-fields{margin-top:22px}.domain-input{display:flex;align-items:stretch}.domain-input input{border-radius:9px 0 0 9px!important}.domain-input span{display:flex;align-items:center;border:1px solid var(--line);border-left:0;border-radius:0 9px 9px 0;padding:0 12px;color:var(--muted);background:var(--surface-alt);white-space:nowrap}.domain-records{display:grid;gap:12px}.domain-records>div{display:grid;grid-template-columns:82px minmax(160px,.7fr) minmax(220px,1fr) 40px;align-items:center;gap:12px;padding:13px;border:1px solid var(--line);border-radius:10px}.domain-records>div>span{font-size:.72rem;font-weight:750;color:var(--muted)}.domain-records code{overflow-wrap:anywhere;font-size:.79rem;background:var(--surface-alt);padding:8px;border-radius:7px}.domain-verify{margin-top:18px;align-items:center;flex-wrap:wrap}.domain-verify small{color:var(--muted)}.domain-verify a{font-weight:700;text-decoration:underline}.domain-provisioning-error{margin-top:16px}@media(max-width:800px){.domain-modes{grid-template-columns:1fr}.domain-records>div{grid-template-columns:1fr 40px}.domain-records>div>span,.domain-records>div>strong{grid-column:1/-1}.domain-input{display:block}.domain-input input{border-radius:9px!important}.domain-input span{border:0;padding:7px 2px;background:none}}
</style>
